<?php if(tienePermiso('caja.rectificar')): ?><div id="modal-rectificar-caja" class="fixed inset-0 z-[80] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-8 max-w-3xl rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Revisar cierre de caja</h2><p id="revision-caja-subtitulo" class="mt-1 text-sm text-slate-500"></p><form method="post" enctype="multipart/form-data" action="index.php?url=cobros_caja_rectificar" data-confirmar-accion="caja-rectificar" class="mt-5 grid gap-4 sm:grid-cols-2"><?= campoCsrf() ?><input id="revision-id-cierre" type="hidden" name="id_cierre"><label class="form-label">Acción<select id="revision-accion" name="accion" class="form-input"><option value="RECTIFICACION">Rectificar declaración</option><option value="JUSTIFICACION">Justificar diferencia real</option><option value="REGULARIZACION">Regularizar con otro movimiento</option></select></label><label class="form-label">Motivo<select id="revision-motivo-tipo" name="motivo_tipo" class="form-input"><option value="ERROR_CONTEO">Error de conteo</option><option value="ERROR_DIGITACION">Error de digitación</option><option value="MOVIMIENTO_OMITIDO">Movimiento omitido</option><option value="DIFERENCIA_REAL">Diferencia real comprobada</option><option value="OTRO">Otro</option></select></label><div id="revision-medios" class="grid gap-3 sm:col-span-2 sm:grid-cols-2 lg:grid-cols-3"></div><label id="revision-referencia-contenedor" class="form-label hidden sm:col-span-2">Referencia de regularización<input id="revision-referencia" maxlength="120" name="referencia_regularizacion" class="form-input" placeholder="Código del movimiento o documento"></label><label class="form-label sm:col-span-2">Explicación obligatoria<textarea required minlength="5" maxlength="500" name="motivo" rows="3" class="form-input" placeholder="Explique qué ocurrió y cómo se verificó"></textarea></label><label class="form-label sm:col-span-2">Evidencia <span class="font-normal text-slate-400">(opcional)</span><input type="file" name="evidencia" accept="image/jpeg,image/png,image/webp,application/pdf" class="mt-2 block w-full text-sm"></label><div class="rounded-xl bg-violet-50 p-3 text-sm text-violet-800 sm:col-span-2">El cierre no se reabrirá. Los valores anteriores permanecerán en el historial de auditoría.</div><button class="rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-semibold text-white sm:col-span-2">Registrar revisión</button></form></div></div>
<section class="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b p-5"><h2 class="font-bold">Historial de rectificaciones y resoluciones</h2><p class="text-sm text-slate-500">Cada intervención conserva la diferencia anterior, la nueva y el responsable.</p></div><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" data-order="1:desc" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="no-sort p-4">N°</th><th class="p-4">Fecha</th><th class="p-4">Turno</th><th class="p-4">Acción</th><th class="p-4">Motivo</th><th class="p-4">Diferencia</th><th class="p-4">Responsable</th><th class="no-sort p-4">Evidencia</th></tr></thead><tbody><?php foreach($rectificaciones as $indice=>$r): ?><tr class="border-t"><td class="p-4"><?= $indice+1 ?></td><td class="p-4"><?= htmlspecialchars($r['registrado_en']) ?></td><td class="p-4"><?= htmlspecialchars($r['fecha']) ?> · #<?= (int)$r['id_apertura'] ?></td><td class="p-4"><span class="rounded-full bg-violet-100 px-2 py-1 text-xs font-semibold text-violet-800"><?= htmlspecialchars($r['accion']) ?></span></td><td class="p-4"><b><?= str_replace('_',' ',htmlspecialchars($r['motivo_tipo'])) ?></b><small class="block max-w-sm text-slate-500"><?= htmlspecialchars($r['motivo']) ?></small><?php if($r['referencia_regularizacion']): ?><small class="block text-blue-600">Ref. <?= htmlspecialchars($r['referencia_regularizacion']) ?></small><?php endif; ?></td><td class="p-4">S/ <?= number_format((float)$r['diferencia_anterior'],2) ?> <i class="bi bi-arrow-right"></i> <b>S/ <?= number_format((float)$r['diferencia_nueva'],2) ?></b></td><td class="p-4"><?= htmlspecialchars($r['responsable']) ?></td><td class="p-4"><?php if($r['evidencia_archivo']): ?><a target="_blank" href="index.php?url=cobros_caja_rectificacion_evidencia&id=<?= (int)$r['id_rectificacion'] ?>" class="inline-flex h-9 w-9 items-center justify-center rounded-lg bg-blue-100 text-blue-700" title="Ver evidencia"><i class="bi bi-paperclip"></i></a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rectificaciones): ?><tr><td colspan="8" class="p-8 text-center text-slate-500">Todavía no existen revisiones de cierres.</td></tr><?php endif; ?></tbody></table></div></section>
<script>
const detalleMediosCierre=<?= json_encode($mediosCierres,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
function abrirRevisionCaja(id,fecha){document.getElementById('revision-id-cierre').value=id;document.getElementById('revision-caja-subtitulo').textContent='Cierre del '+fecha+' · registro #'+id;const contenedor=document.getElementById('revision-medios');contenedor.innerHTML='';(detalleMediosCierre[id]||[]).forEach(m=>{const label=document.createElement('label');label.className='form-label';label.innerHTML=`${m.medio} declarado<input type="number" step="0.01" ${m.medio==='EFECTIVO'?'min="0"':''} name="declarados[${m.medio}]" value="${Number(m.importe_declarado).toFixed(2)}" class="form-input revision-importe"><small class="mt-1 block font-normal text-slate-500">Sistema: S/ ${Number(m.importe_sistema).toFixed(2)} · diferencia: S/ ${Number(m.diferencia).toFixed(2)}</small>`;contenedor.appendChild(label)});document.getElementById('revision-accion').value='RECTIFICACION';actualizarTipoRevision();document.getElementById('modal-rectificar-caja').classList.remove('hidden')}
function actualizarTipoRevision(){const accion=document.getElementById('revision-accion').value,rectificar=accion==='RECTIFICACION',regularizar=accion==='REGULARIZACION';document.querySelectorAll('.revision-importe').forEach(i=>i.readOnly=!rectificar);document.getElementById('revision-referencia-contenedor').classList.toggle('hidden',!regularizar);document.getElementById('revision-referencia').required=regularizar;const motivo=document.getElementById('revision-motivo-tipo');if(rectificar&&!['ERROR_CONTEO','ERROR_DIGITACION','OTRO'].includes(motivo.value))motivo.value='ERROR_CONTEO'}
document.addEventListener('DOMContentLoaded',()=>document.getElementById('revision-accion')?.addEventListener('change',actualizarTipoRevision));
</script><?php endif; ?>
